list_pages.code:
final response = await client.pages.listPages(queryParams: {
  'search': 'about',
  'visibility': 'open',
  'sort': 'name',
  'order': 'asc',
});
final pages = (response.map as Map)['pages'] as List;
for (final page in pages) {
  print('${(page as Map)['id']} ${page['name']} ${page['url']}');
}

count_pages.code:
final response = await client.pages
    .countPages(queryParams: {'active': true, 'has_layout': true});
print((response.map as Map)['total']);

create_page.code:
final response = await client.pages.createPage({
  'page': {
    'name': 'About us',
    'title': 'About us',
    'visibility': 'open',
    'layout': {'id': 28},
  },
});
final page = (response.map as Map)['page'] as Map;
print('${page['id']} ${page['url']}');

get_page.code:
final response = await client.pages.getPage(812);
final page = (response.map as Map)['page'] as Map;
print('${page['name']} ${page['visibility']} ${page['in_trash']}');
print(response.headers['etag']);

head_page.code:
final response = await client.pages.headPage(812);
print(response.statusCode);
print(response.headers['etag']);

update_page.code:
final response = await client.pages.updatePage(812, {
  'page': {
    'name': 'About us',
    'title': 'About us',
    'subtitle': 'Who we are',
    'url': 'about-us',
    'layout': {'id': 28},
    'visibility': 'open',
    'body_class': 'about-page',
    'active': true,
    'disable_tracking': false,
    'password_protection': {'enabled': false},
  },
});
final page = (response.map as Map)['page'] as Map;
print('${page['subtitle']} ${page['body_class']}');

